Declare a class with std::vector or std::string members and rely on default behaviors:

class MyClass {
private:
    std::vector<int> data;  // Automatically manages a dynamic array
    std::string text;      // Automatically manages a string with proper copying
public:
    // No custom copy constructor, assignment operator, or destructor needed
    void addData(int value) { data.push_back(value); }  // Practical usage example
};

Practical usage notes: Always include necessary headers (<vector> and <string>), and ensure the class doesn't mix with raw pointers or other unmanaged resources, which might require custom implementations to avoid pitfalls like undefined behavior during copying.

code_example:
#include <vector>
#include <string>
#include <iostream>

class BookCollection {
private:
    std::vector<std::string> books;  // A vector to store book titles

public:
    // Default constructor, copy constructor, assignment, and destructor are sufficient
    void addBook(const std::string& bookTitle) {
        books.push_back(bookTitle);  // Adds a book to the collection
    }

    void displayBooks() const {
        for (const auto& book : books) {
            std::cout << book << std::endl;  // Iterates and prints books
        }
    }
};

int main() {
    BookCollection collection1;
    collection1.addBook("C++ Primer");
    collection1.addBook("Effective C++");

    BookCollection collection2 = collection1;  // Deep copy: collection2 gets its own vector copy
    collection2.displayBooks();  // Outputs the books in collection2
    return 0;
}
